(async()=>{const source=fs.readFileSync(path.join(__dirname,'1-master.png'));const {data:master,info}=await sharp(source).removeAlpha().raw().toBuffer({resolveWithObject:true});const rect=[960,585,1125,695],threshold=110,dilate=3,frames=[];for(const file of process.argv.slice(2)){const input=fs.readFileSync(path.join(__dirname,file)),raw=await sharp(input).removeAlpha().raw().toBuffer();if(raw.length!==master.length)throw Error('Dimensions differ');const out=Buffer.from(raw),mask=new Uint8Array(info.width*info.height);const [x0,y0,x1,y1]=rect;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const p=(y*info.width+x)*3;if(Math.min(...master.subarray(p,p+3))>=threshold||Math.min(...raw.subarray(p,p+3))>=threshold){for(let yy=Math.max(y0,y-dilate);yy<Math.min(y1,y+dilate+1);yy++)for(let xx=Math.max(x0,x-dilate);xx<Math.min(x1,x+dilate+1);xx++)mask[yy*info.width+xx]=1;}}let changed=0,outside=0;for(let p=0;p<mask.length;p++){if(mask[p]){if(!raw.subarray(p*3,p*3+3).equals(master.subarray(p*3,p*3+3)))changed++;master.copy(out,p*3,p*3,p*3+3);}}for(let p=0;p<mask.length;p++)if(!mask[p]&&!out.subarray(p*3,p*3+3).equals(raw.subarray(p*3,p*3+3)))outside++;if(outside)throw Error('Changed outside mask');const target=file.replace('.png','-fixed-shoe.png');await sharp(out,{raw:{width:info.width,height:info.height,channels:3}}).png().toFile(path.join(__dirname,target));frames.push({file,target,inputSha256:hash(input),outputSha256:hash(fs.readFileSync(path.join(__dirname,target))),changedPixels:changed,changedOutsideMask:outside,changedOutsideRectangles:outside});}const record={authorization:'Prior user response: Use this method for fixed areas; question explicitly covered remaining exercise sets, stationary equipment and planted contacts.',method:'Exact frozen-master RGB copy inside union-white shoe silhouette, dilated 3px and bounded to fixed planted shoe. No rescaling or moving anatomy edits.',masterSha256:hash(source),rect,threshold,dilate,frames};fs.writeFileSync(path.join(__dirname,'fixed-shoe-provenance.json'),JSON.stringify(record,null,2)+'\n');console.log(JSON.stringify(record,null,2));})();

